// COMP4G hosted qualification for signed char function parameters and returns.
// The suite executes AMD64 generated by the production parser/backend and
// exercises the production object, linker, and final-ELF pipeline.

#include "core/compiler/compiler_diagnostics.h"
#include "core/compiler/compiler_lexer.h"
#include "core/compiler/compiler_linker.h"
#include "core/compiler/compiler_module.h"
#include "core/compiler/compiler_object.h"
#include "core/compiler/compiler_parser.h"
#include "core/compiler/elf_writer.h"
#include "arch/amd64/compiler_backend.h"

#include <cstdio>
#include <cstring>

#if defined(_WIN32)
#include <windows.h>
#endif

using namespace kernel::compiler;

namespace {

static TranslationUnitIR g_unit = {};
static Token g_tokens[COMPILER_MAX_TOKENS] = {};
static CallSite g_calls[COMPILER_MAX_FUNCTIONS][COMPILER_MAX_CALL_EXPRESSIONS] = {};
static uint16_t g_arguments[COMPILER_MAX_FUNCTIONS][COMPILER_MAX_CALL_ARGUMENT_NODES] = {};
static uint8_t g_data[COMPILER_MAX_TOTAL_STRING_DATA] = {};
static uint32_t g_dataBytes = 0;
static uint8_t g_code[COMPILER_MAX_CODE_BYTES] = {};
static uint32_t g_codeBytes = 0;
static uint32_t g_entryOffset = 0;
static CompiledModule g_objectModules[2] = {};
static CompiledModule g_roundTripModules[2] = {};
static uint8_t g_objectBytes[2][COMPILER_MAX_OBJECT_BYTES] = {};
static uint32_t g_objectByteCounts[2] = {};
static LinkedProgram g_linked = {};
static uint8_t g_finalElf[BOOTSTRAP_MAX_ELF_BYTES] = {};
static uint32_t g_assertionCount = 0;

static bool require(bool condition, const char* message)
{
    ++g_assertionCount;
    if (!condition) std::fprintf(stderr, "FAIL: %s\n", message);
    return condition;
}

static bool diagnostic_contains(const Diagnostics& diagnostics, const char* needle)
{
    for (uint32_t i = 0; i < diagnostics.count(); ++i) {
        const char* message = diagnostics.at(i).message;
        if (message && std::strstr(message, needle)) return true;
    }
    return false;
}

static bool compile_source(const char* source, Diagnostics* diagnostics)
{
    if (!source || !diagnostics) return false;
    const uint32_t sourceBytes = static_cast<uint32_t>(std::strlen(source));
    uint32_t tokenCount = 0;
    g_unit = {};
    g_dataBytes = 0;
    g_codeBytes = 0;
    g_entryOffset = 0;
    if (!lex_source(source, sourceBytes, g_tokens, COMPILER_MAX_TOKENS,
                    &tokenCount, *diagnostics) ||
        !parse_translation_unit(source, g_tokens, tokenCount, &g_unit, *diagnostics,
                                &g_calls[0][0], &g_arguments[0][0])) return false;
    for (uint32_t f = 0; f < g_unit.functionCount; ++f) {
        FunctionIR& function = g_unit.functions[f];
        const uint32_t functionStart = g_dataBytes;
        function.dataOffset = functionStart;
        for (uint32_t i = 0; i < function.stringCount; ++i) {
            const StringLiteral& literal = function.strings[i];
            if (function.stringOffsets[i] != g_dataBytes - functionStart ||
                g_dataBytes + literal.bytes + 1U > sizeof(g_data)) return false;
            for (uint32_t j = 0; j < literal.bytes; ++j)
                g_data[g_dataBytes + j] = static_cast<uint8_t>(literal.data[j]);
            g_data[g_dataBytes + literal.bytes] = 0;
            g_dataBytes += literal.bytes + 1U;
        }
    }
    const uint64_t dataAddress = g_dataBytes == 0 ? 0 :
        BOOTSTRAP_IMAGE_BASE + BOOTSTRAP_DATA_OFFSET;
    if (!amd64::emit_translation_unit(g_unit, dataAddress, g_code, sizeof(g_code),
                                      &g_codeBytes, &g_entryOffset)) {
        std::fprintf(stderr, "character function backend emission failed\n");
        return false;
    }
    return true;
}

struct CallResult {
    int32_t value;
    uint32_t runtimeFailure;
    uint32_t runtimeDepth;
};

static CallResult call_generated_entry(void* entry)
{
    CallResult result = {};
#if defined(_WIN32) && (defined(__GNUC__) || defined(__clang__))
    asm volatile(
        "pushq %%r14\n\t"
        "pushq %%r15\n\t"
        "subq $64, %%rsp\n\t"
        "movq %[output], 32(%%rsp)\n\t"
        "xorq %%rcx, %%rcx\n\t"
        "call *%[entry]\n\t"
        "movq 32(%%rsp), %%r11\n\t"
        "movl %%r15d, 4(%%r11)\n\t"
        "movl %%r15d, %%r10d\n\t"
        "shrl $8, %%r10d\n\t"
        "movl %%r10d, 8(%%r11)\n\t"
        "addq $64, %%rsp\n\t"
        "popq %%r15\n\t"
        "popq %%r14\n\t"
        : "=a"(result.value)
        : [entry] "r"(entry), [output] "r"(&result)
        : "rcx", "rdx", "r8", "r9", "r10", "r11", "memory");
#else
    (void)entry;
#endif
    return result;
}

static CallResult execute_code(const uint8_t* code, uint32_t codeBytes,
                               uint32_t entryOffset)
{
    CallResult result = {};
#if defined(_WIN32)
    if (!code || codeBytes == 0 || entryOffset >= codeBytes) return result;
    void* memory = VirtualAlloc(nullptr, codeBytes, MEM_COMMIT | MEM_RESERVE,
                                PAGE_READWRITE);
    if (!memory) return result;
    std::memcpy(memory, code, codeBytes);
    DWORD oldProtection = 0;
    const bool executable = VirtualProtect(memory, codeBytes, PAGE_EXECUTE_READ,
                                            &oldProtection) != 0;
    FlushInstructionCache(GetCurrentProcess(), memory, codeBytes);
    if (executable)
        result = call_generated_entry(static_cast<uint8_t*>(memory) + entryOffset);
    VirtualFree(memory, 0, MEM_RELEASE);
#else
    (void)code;
    (void)codeBytes;
    (void)entryOffset;
#endif
    return result;
}

static bool contains_bytes(const uint8_t* code, uint32_t codeBytes,
                           const uint8_t* needle, uint32_t needleBytes)
{
    if (!code || !needle || needleBytes == 0 || needleBytes > codeBytes) return false;
    for (uint32_t i = 0; i + needleBytes <= codeBytes; ++i)
        if (std::memcmp(code + i, needle, needleBytes) == 0) return true;
    return false;
}

static bool expect_rejection(const char* source, CompilerDiagnosticKind kind,
                             const char* message)
{
    Diagnostics diagnostics;
    const bool accepted = compile_source(source, &diagnostics);
    const bool valid = !accepted && diagnostics.count() != 0 &&
        diagnostics.at(0).kind == kind &&
        diagnostics.at(0).location.line != 0 &&
        diagnostics.at(0).location.column != 0 &&
        diagnostic_contains(diagnostics, message);
    if (!valid) {
        std::fprintf(stderr, "rejection mismatch: kind=%u message=%s accepted=%u count=%u\n",
                     static_cast<unsigned>(kind), message, accepted ? 1U : 0U,
                     diagnostics.count());
        if (diagnostics.count())
            std::fprintf(stderr, "observed kind=%u at %u:%u: %s\n",
                         static_cast<unsigned>(diagnostics.at(0).kind),
                         diagnostics.at(0).location.line,
                         diagnostics.at(0).location.column,
                         diagnostics.at(0).message);
    }
    return require(valid, "invalid signature or expression has a located diagnostic");
}

static bool test_generated_parameter_and_return_execution()
{
    const char* source =
        "char echo(char value) { return value; }\n"
        "char successor(char value) { return value + 1; }\n"
        "char combine(char left, char right) { return left + right; }\n"
        "char add_amount(char value, int amount) { return value + amount; }\n"
        "int add_integer(int amount, char value) { return amount + value; }\n"
        "int mixed(char a, int b, char c, int d) { return a + b + c + d; }\n"
        "char rewrite(char value) { value = 255; return value; }\n"
        "char keep_second(char first, char second) { first = 255; return second; }\n"
        "char nested(char value) { return successor(echo(value)); }\n"
        "int string_pointer_compatibility(char* text) { return 7; }\n"
        "int gx_main(gx_app_context* ctx) {\n"
        "  if (echo(127) != 127) return 1;\n"
        "  if (echo(128) != -128 || echo(255) != -1) return 2;\n"
        "  if (echo(-129) != 127 || echo(258) != 2) return 3;\n"
        "  if (successor(127) != -128 || successor(-128) != -127) return 4;\n"
        "  if (combine(100, 100) != -56 || keep_second(1, 65) != 65) return 5;\n"
        "  if (rewrite(0) != -1 || add_amount('A', 2) != 'C') return 6;\n"
        "  if (add_amount(255, -1) != -2 || add_integer(10, 255) != 9) return 7;\n"
        "  if (mixed(1, 2, 3, 4) != 10) return 81;\n"
        "  if (nested(65) != 66) return 82;\n"
        "  if (string_pointer_compatibility(\"text\") != 7) return 9;\n"
        "  if (echo(-7) / 2 != -3 || echo(-7) % 2 != -1) return 10;\n"
        "  return 66;\n"
        "}\n";
    Diagnostics diagnostics;
    if (!compile_source(source, &diagnostics)) {
        for (uint32_t i = 0; i < diagnostics.count(); ++i)
            std::fprintf(stderr, "character function diagnostic: %s\n", diagnostics.at(i).message);
        return require(false, "mixed char parameter/return source compiles with production AMD64 backend");
    }

    const uint8_t localByteStore[] = {0x88, 0x85};
    const uint8_t localByteLoadSigned[] = {0x0F, 0xBE, 0x85};
    const uint8_t firstArgumentByteStore[] = {0x88, 0x8D}; // [rbp+disp32], CL
    const uint8_t r8ArgumentByteStore[] = {0x44, 0x88, 0x85};
    const uint8_t charReturnNormalize[] = {0x0F, 0xBE, 0xC0}; // movsx eax, al
    const uint8_t callHomeSpaceReserve[] = {0x48, 0x83, 0xEC, 0x20};
    const uint8_t callHomeSpaceRelease[] = {0x48, 0x83, 0xC4, 0x20};
    if (!require(contains_bytes(g_code, g_codeBytes, localByteStore, sizeof(localByteStore)) &&
                 contains_bytes(g_code, g_codeBytes, localByteLoadSigned, sizeof(localByteLoadSigned)),
                 "character parameter assignment and read use byte store and signed byte load")) return false;
    if (!require(contains_bytes(g_code, g_codeBytes, firstArgumentByteStore,
                               sizeof(firstArgumentByteStore)) &&
                 contains_bytes(g_code, g_codeBytes, r8ArgumentByteStore,
                               sizeof(r8ArgumentByteStore)),
                 "character parameters in ECX and R8D are copied from their low-byte registers")) return false;
    if (!require(contains_bytes(g_code, g_codeBytes, charReturnNormalize,
                               sizeof(charReturnNormalize)),
                 "char returns truncate to AL then sign extend into EAX")) return false;
    if (!require(contains_bytes(g_code, g_codeBytes, callHomeSpaceReserve,
                               sizeof(callHomeSpaceReserve)) &&
                 contains_bytes(g_code, g_codeBytes, callHomeSpaceRelease,
                               sizeof(callHomeSpaceRelease)),
                 "internal calls reserve and release the 32-byte home space with aligned RSP")) return false;

    const FunctionIR* mixedFunction = nullptr;
    const FunctionIR* echoFunction = nullptr;
    for (uint32_t i = 0; i < g_unit.functionCount; ++i) {
        if (std::strcmp(g_unit.functions[i].name, "mixed") == 0) mixedFunction = &g_unit.functions[i];
        if (std::strcmp(g_unit.functions[i].name, "echo") == 0) echoFunction = &g_unit.functions[i];
    }
    if (!require(mixedFunction && mixedFunction->parameterStorageBytes == 16 &&
                 mixedFunction->parameters[0].stackOffsetBytes == 1 &&
                 mixedFunction->parameters[1].stackOffsetBytes == 8 &&
                 mixedFunction->parameters[2].stackOffsetBytes == 9 &&
                 mixedFunction->parameters[3].stackOffsetBytes == 16,
                 "mixed parameters have byte-accurate, aligned frame ownership")) return false;
    if (!require(echoFunction && echoFunction->returnKind == FunctionReturnKind::Character &&
                 echoFunction->parameterStorageBytes == 1 &&
                 echoFunction->parameters[0].kind == ParameterKind::Character,
                 "char signatures retain signed-byte parameter and return types in IR")) return false;

    const CallResult result = execute_code(g_code, g_codeBytes, g_entryOffset);
#if defined(_WIN32)
    if (result.value != 66 || result.runtimeFailure != 0)
        std::fprintf(stderr, "generated char suite result=%d failure=%u depth=%u\n",
                     result.value, result.runtimeFailure, result.runtimeDepth);
    return require(result.value == 66 && result.runtimeFailure == 0,
                   "generated AMD64 executes nested, mixed, boundary, repeated-call, and signed division cases");
#else
    (void)result;
    return require(false, "this suite requires the Windows AMD64 hosted execution harness");
#endif
}

static bool compile_module_text(const char* path, const char* source,
                                CompiledModule* module, Diagnostics* diagnostics)
{
    return path && source && module && diagnostics &&
        compile_module_from_source(path, source,
            static_cast<uint32_t>(std::strlen(source)), module, *diagnostics);
}

static bool test_object_link_elf_and_cross_module_execution()
{
    const char* consumer =
        "extern char adjust(char);\n"
        "int gx_main(gx_app_context* ctx) {\n"
        "  if (adjust(127) != -128) return 51;\n"
        "  return adjust(64);\n"
        "}\n";
    const char* provider = "char adjust(char value) { return value + 1; }\n";
    Diagnostics consumerDiagnostics;
    Diagnostics providerDiagnostics;
    if (!compile_module_text("src/main.cpp", consumer, &g_objectModules[0], &consumerDiagnostics) ||
        !compile_module_text("src/adjust.cpp", provider, &g_objectModules[1], &providerDiagnostics)) {
        for (uint32_t i = 0; i < consumerDiagnostics.count(); ++i)
            std::fprintf(stderr, "consumer diagnostic: %s\n", consumerDiagnostics.at(i).message);
        for (uint32_t i = 0; i < providerDiagnostics.count(); ++i)
            std::fprintf(stderr, "provider diagnostic: %s\n", providerDiagnostics.at(i).message);
        return require(false, "character prototypes and definitions compile into production modules");
    }
    if (!require(g_objectModules[0].importCount == 1 &&
                 g_objectModules[0].imports[0].parameterKinds[0] == ParameterKind::Character &&
                 g_objectModules[0].imports[0].expectedReturnKind == FunctionReturnKind::Character &&
                 g_objectModules[1].exports[0].parameterKinds[0] == ParameterKind::Character &&
                 g_objectModules[1].exports[0].returnKind == FunctionReturnKind::Character,
                 "module import/export metadata preserves char parameter and return signatures")) return false;

    for (uint32_t i = 0; i < 2; ++i) {
        if (!serialize_elf_object(g_objectModules[i], g_objectBytes[i],
                                  sizeof(g_objectBytes[i]), &g_objectByteCounts[i]))
            return require(false, "production modules serialize as ELF objects");
        Diagnostics objectDiagnostics;
        ElfObjectHeaderView header = {};
        if (!inspect_elf_object(g_objectBytes[i], g_objectByteCounts[i],
                                &header, objectDiagnostics) ||
            header.compilerObjectAbiVersion != 13 || header.formatVersion != 2 ||
            !deserialize_elf_object(g_objectBytes[i], g_objectByteCounts[i],
                                    &g_roundTripModules[i], objectDiagnostics))
            return require(false, "ELF object round trip accepts ABI 13 and preserves signatures");
    }
    if (!require(g_roundTripModules[0].imports[0].parameterKinds[0] == ParameterKind::Character &&
                 g_roundTripModules[0].imports[0].expectedReturnKind == FunctionReturnKind::Character &&
                 g_roundTripModules[1].exports[0].returnKind == FunctionReturnKind::Character,
                 "ELF object metadata round trips typed character signatures")) return false;

    Diagnostics linkDiagnostics;
    if (!link_modules(g_roundTripModules, 2, &g_linked, linkDiagnostics)) {
        for (uint32_t i = 0; i < linkDiagnostics.count(); ++i)
            std::fprintf(stderr, "link diagnostic: %s\n", linkDiagnostics.at(i).message);
        return require(false, "serialized character modules link with production linker");
    }
    ElfLayout layout = {};
    if (!write_bootstrap_elf(g_linked.code, g_linked.codeBytes,
                             g_linked.data, g_linked.dataBytes,
                             g_linked.mutableData, g_linked.mutableDataBytes,
                             g_linked.entryCodeOffset, g_finalElf, sizeof(g_finalElf), &layout))
        return require(false, "linked character modules produce a final NativeElf image");
    ElfValidationResult validation = {};
    if (!validate_bootstrap_elf(g_finalElf, layout.outputBytes, layout.imageBase,
                                layout.codeOffset, g_linked.code, g_linked.codeBytes,
                                &validation, g_linked.data, g_linked.dataBytes,
                                g_linked.entryCodeOffset))
        return require(false, "final NativeElf image validates against linked AMD64 bytes");

    const CallResult result = execute_code(g_finalElf + layout.codeOffset,
                                           g_linked.codeBytes,
                                           g_linked.entryCodeOffset);
#if defined(_WIN32)
    return require(result.value == 65 && result.runtimeFailure == 0,
                   "object-to-ELF cross-module character call executes with signed return promotion");
#else
    (void)result;
    return require(false, "this suite requires the Windows AMD64 hosted execution harness");
#endif
}

static bool test_signature_and_resource_diagnostics()
{
    return expect_rejection(
               "int convert(char value); char convert(char value) { return value; }\n"
               "int gx_main(gx_app_context* ctx) { return convert(1); }",
               CompilerDiagnosticKind::Semantic, "conflicting declaration for function") &&
           expect_rejection(
               "int choose(char value); int choose(int value);\n"
               "int gx_main(gx_app_context* ctx) { return choose(1); }",
               CompilerDiagnosticKind::Semantic, "conflicting declaration for function") &&
           expect_rejection("char* text_value() { return \"text\"; }",
               CompilerDiagnosticKind::Unsupported, "character-pointer function return types") &&
           expect_rejection("int bad_pointer(char** text) { return 0; }",
               CompilerDiagnosticKind::Syntax, "expected parameter identifier") &&
           expect_rejection("char bad_return(char value) { return \"text\"; }",
               CompilerDiagnosticKind::Unsupported, "char functions require an int expression") &&
           expect_rejection("char missing_return(char value) { return; }",
               CompilerDiagnosticKind::Syntax, "expected expression") &&
           expect_rejection("char malformed(char value { return value; }",
               CompilerDiagnosticKind::Syntax, "expected ')' after parameter list") &&
           expect_rejection(
               "int needs_text(char* text) { return 1; }\n"
               "int gx_main(gx_app_context* ctx) { return needs_text(65); }",
               CompilerDiagnosticKind::Semantic, "function argument requires char*") &&
           expect_rejection(
               "char too_many(char a, char b, char c, char d, char e) { return a; }",
               CompilerDiagnosticKind::ResourceLimit, "function parameter limit exceeded") &&
           expect_rejection(
               "int four(int a, int b, int c, int d) { return a; }\n"
               "int gx_main(gx_app_context* ctx) { return four(1, 2, 3, 4, 5); }",
               CompilerDiagnosticKind::ResourceLimit, "function call exceeds four-argument limit");
}

static bool test_cross_module_conflicting_return_rejected()
{
    CompiledModule consumer = {};
    CompiledModule provider = {};
    Diagnostics consumerDiagnostics;
    Diagnostics providerDiagnostics;
    if (!compile_module_text("src/main.cpp",
            "int adjust(char); int gx_main(gx_app_context* ctx) { return adjust(65); }",
            &consumer, &consumerDiagnostics) ||
        !compile_module_text("src/adjust.cpp", "char adjust(char value) { return value; }",
            &provider, &providerDiagnostics))
        return require(false, "mismatched cross-module fixtures compile independently");
    CompiledModule modules[2] = {consumer, provider};
    LinkedProgram linked = {};
    Diagnostics diagnostics;
    return require(!link_modules(modules, 2, &linked, diagnostics) &&
                   diagnostic_contains(diagnostics, "conflicting declaration for function 'adjust'"),
                   "linker rejects mismatched cross-module return types");
}

} // namespace

int main()
{
    if (!test_generated_parameter_and_return_execution() ||
        !test_object_link_elf_and_cross_module_execution() ||
        !test_signature_and_resource_diagnostics() ||
        !test_cross_module_conflicting_return_rejected()) return 1;
    std::printf("compiler_character_functions_host_test: PASS (%u assertions)\n",
                g_assertionCount);
    return 0;
}
